const verifyPassword=(v,stored)=>{if(!stored)return true;if(!stored.startsWith('scrypt$'))return stored===hashToken(v);const [,salt,hex]=stored.split('$');if(!salt||!hex)return false;const actual=crypto.scryptSync(String(v||''),salt,32);const expected=Buffer.from(hex,'hex');return expected.length===actual.length&&crypto.timingSafeEqual(expected,actual)};
