function blankRoom(code){return {code,exists:false,status:'lobby',pace:'campaign',passwordHash:null,clients:new Set(),players:new Map(),countryOwners:new Map(),snapshot:null,revision:0,createdAt:Date.now(),lastActivity:Date.now(),hostPlayerId:null,turnDeadline:null,reports:[],dirty:false}}
function serializable(room){return {code:room.code,exists:true,status:room.status,pace:safePace(room.pace),passwordHash:room.passwordHash,revision:room.revision,snapshot:room.snapshot,countryOwners:Object.fromEntries(room.countryOwners),players:[...room.players.values()].map(p=>({id:p.id,country:p.country||null,tokenHash:p.tokenHash,joinedAt:p.joinedAt,lastSeen:p.lastSeen,name:p.name||'لاعب',ready:!!p.ready,turnReady:!!p.turnReady,surrendered:!!p.surrendered,installHash:p.installHash||null})),hostPlayerId:room.hostPlayerId,turnDeadline:room.turnDeadline,reports:room.reports||[],createdAt:room.createdAt,lastActivity:room.lastActivity}}
function hydrate(data){const r=blankRoom(data.code);r.exists=true;r.status=data.status||((data.snapshot)?'running':'lobby');r.pace=safePace(data.pace||data.snapshot?.gamePace);r.passwordHash=data.passwordHash||null;r.revision=Number(data.revision||0);r.snapshot=data.snapshot||null;r.countryOwners=new Map(Object.entries(data.countryOwners||{}));r.players=new Map((data.players||[]).map(p=>[p.id,{...p,ready:!!p.ready,turnReady:!!p.turnReady,surrendered:!!p.surrendered}]));r.hostPlayerId=data.hostPlayerId||null;r.turnDeadline=data.turnDeadline||null;r.reports=Array.isArray(data.reports)?data.reports.slice(-500):[];r.createdAt=Number(data.createdAt||Date.now());r.lastActivity=Number(data.lastActivity||Date.now());return r}
async function initDb(){if(!db)return;await db.query(`create table if not exists world_dominion_rooms(code text primary key,state jsonb not null,updated_at timestamptz not null default now())`);await db.query(`create table if not exists world_dominion_bans(install_hash text primary key,reason text not null,created_at timestamptz not null default now(),expires_at timestamptz null)`)}
async function loadRoom(code){if(rooms.has(code))return rooms.get(code);let data=null;if(db){const q=await db.query('select state from world_dominion_rooms where code=$1',[code]);data=q.rows[0]?.state||null}else{try{data=JSON.parse(await fs.readFile(path.join(localSaveDir,`${code}.json`),'utf8'))}catch{}}
 if(data&&Date.now()-Number(data.lastActivity||data.createdAt||Date.now())>dataRetentionMs){await deletePersistedRoom(code);data=null}
 const room=data?hydrate(data):blankRoom(code);rooms.set(code,room);return room}
async function persistRoom(room){room.dirty=false;const data=serializable(room);if(db){await db.query('insert into world_dominion_rooms(code,state,updated_at) values($1,$2,now()) on conflict(code) do update set state=excluded.state,updated_at=now()',[room.code,data])}else{await fs.mkdir(localSaveDir,{recursive:true});await fs.writeFile(path.join(localSaveDir,`${room.code}.json`),JSON.stringify(data),'utf8')}}
async function deletePersistedRoom(code){if(db){await db.query('delete from world_dominion_rooms where code=$1',[code])}else{try{await fs.unlink(path.join(localSaveDir,`${code}.json`))}catch{}}}
async function localBans(){try{return JSON.parse(await fs.readFile(path.join(localSaveDir,'bans.json'),'utf8'))}catch{return {bans:[]}}}
async function isInstallBanned(installHash){if(!installHash)return false;const now=Date.now();if(db){const q=await db.query('select 1 from world_dominion_bans where install_hash=$1 and (expires_at is null or expires_at>now())',[installHash]);return q.rowCount>0}const data=await localBans();return (data.bans||[]).some(b=>b.installHash===installHash&&(!b.expiresAt||Number(b.expiresAt)>now))}
async function addInstallBan(installHash,reason='abuse',days=30){if(!installHash)return false;const expiresAt=days>0?Date.now()+days*86_400_000:null;if(db){await db.query('insert into world_dominion_bans(install_hash,reason,expires_at) values($1,$2,$3) on conflict(install_hash) do update set reason=excluded.reason,created_at=now(),expires_at=excluded.expires_at',[installHash,reason,expiresAt?new Date(expiresAt):null])}else{await fs.mkdir(localSaveDir,{recursive:true});const data=await localBans();data.bans=(data.bans||[]).filter(b=>b.installHash!==installHash);data.bans.push({installHash,reason,createdAt:Date.now(),expiresAt});await fs.writeFile(path.join(localSaveDir,'bans.json'),JSON.stringify(data),'utf8')}return true}
async function readJsonBody(req,maxBytes=16_384){return await new Promise((resolve,reject)=>{let body='';req.on('data',c=>{body+=c;if(body.length>maxBytes){reject(new Error('payload_too_large'));req.destroy()}});req.on('end',()=>{try{resolve(body?JSON.parse(body):{})}catch(e){reject(e)}});req.on('error',reject)})}
async function enforceBan(installHash){for(const room of rooms.values()){let changed=false;for(const p of room.players.values()){if(p.installHash!==installHash||p.surrendered)continue;p.surrendered=true;p.turnReady=true;if(room.snapshot&&p.country){const ctrl=`P:${p.country}`;for(const c of Object.values(room.snapshot.countries||{}))if(c.controller===ctrl)c.controller=`AI:${p.country}`}changed=true;for(const client of room.clients)if(client.playerId===p.id){send(client,{type:'error',code:'banned',message:'Access blocked by moderation'});setTimeout(()=>client.close(4003,'banned'),50)}}if(changed){if(room.snapshot)mutate(room,'تمت إزالة لاعب من الخدمة بواسطة الإشراف.');markDirty(room);await persistRoom(room)}}}
async function allModerationReports(){
 const out=[];
 if(db){
  const q=await db.query(`select code,state from world_dominion_rooms where jsonb_array_length(coalesce(state->'reports','[]'::jsonb))>0 order by updated_at desc limit 500`);
  for(const row of q.rows){for(const r of (row.state?.reports||[]))out.push({room:row.code,...r})}
 }else{
  try{for(const file of await fs.readdir(localSaveDir)){if(!file.endsWith('.json'))continue;try{const state=JSON.parse(await fs.readFile(path.join(localSaveDir,file),'utf8'));for(const r of (state.reports||[]))out.push({room:state.code||file.replace(/\.json$/,''),...r})}catch{}}}catch{}
 }
 // Dirty in-memory rooms may be newer than their persisted copy. Prefer the newest report id once.
 for(const room of rooms.values())for(const r of (room.reports||[]))out.push({room:room.code,...r});
 const unique=new Map();for(const r of out)unique.set(`${r.room}:${r.id}`,r);
 return [...unique.values()].sort((a,b)=>Number(a.at||0)-Number(b.at||0)).slice(-500);
}
function markDirty(room){room.dirty=true;room.lastActivity=Date.now()}
function broadcast(room,obj,except=null){for(const c of room.clients)if(c!==except)send(c,obj)}
function playerController(room,playerId){const p=room.players.get(playerId);return p?.country?`P:${p.country}`:null}
function syncTo(ws,room){send(ws,{type:'sync',revision:room.revision,snapshot:snapshotForObserver(room.snapshot,playerController(room,ws.playerId)),from:'server'})}
function broadcastSync(room){for(const c of room.clients)syncTo(c,room)}
function lobbyPayload(room){return {type:'lobby',room:room.code,status:room.status,pace:safePace(room.pace),turnSeconds:roomTurnSeconds(room),revision:room.revision,hostPlayerId:room.hostPlayerId,turnDeadline:room.turnDeadline,players:[...room.players.values()].map(p=>({id:p.id,country:p.country||null,name:p.name||'لاعب',ready:!!p.ready,turnReady:!!p.turnReady,surrendered:!!p.surrendered,online:[...room.clients].some(c=>c.playerId===p.id)})),countryOwners:Object.fromEntries(room.countryOwners)}}
function pushLog(room,text){if(!room.snapshot)return;room.snapshot.logs=Array.isArray(room.snapshot.logs)?room.snapshot.logs:[];room.snapshot.logs.unshift(`الدور ${room.snapshot.turn||1} — ${text}`);room.snapshot.logs=room.snapshot.logs.slice(0,100)}
function updateEliminatedPlayers(room){
 if(!room.snapshot?.countries)return;
 const controllers=new Set(Object.values(room.snapshot.countries).map(c=>c.controller));
 for(const p of room.players.values()){
  if(!p.country||p.surrendered)continue;
  if(!controllers.has(`P:${p.country}`)){
   p.surrendered=true;p.turnReady=true;
   pushLog(room,`${p.name||'لاعب'} خسر آخر إقليم وأصبح متفرجاً.`);
  }
 }
}
function techLevel(c,key){return clamp(Number(c?.[key]||0),0,5)}
function commandCap(c,pace='campaign'){return commandBaseForPace(pace)+techLevel(c,'techLogistics')}
function roomTurnSeconds(room){return turnSecondsForPace(room?.pace,TURN_SECONDS_OVERRIDE)}
function spendCommand(c,amount){const have=Number(c.commandPoints??commandCap(c));if(have<amount)return false;c.commandPoints=have-amount;return true}
function combatPower(country,army=country?.army||{}){
 const armor=1+techLevel(country,'techArmor')*.06,air=1+techLevel(country,'techAir')*.06;
 return Number(army.soldiers||0)+Number(army.tanks||0)*3.2*armor+Number(army.artillery||0)*2.7*armor+Number(army.airDefense||0)*2.2+Number(army.aircraft||0)*4.5*air+Number(army.helicopters||0)*3.5*air+Number(army.drones||0)*2*air+Number(army.recon||0)*1.5+Number(army.navy||0)*4;
}
function controllerScore(room,controller){
 const owned=Object.values(room.snapshot?.countries||{}).filter(c=>c.controller===controller);if(!owned.length)return 0;
 const territory=owned.length*24,pop=owned.reduce((n,c)=>n+Number(c.population||0),0)*.02;
 const economy=owned.reduce((n,c)=>n+Number(c.stock?.money||0)*.08+Number(c.stock?.steel||0)*.06+Number(c.production?.money||0)*.8,0);
 const military=owned.reduce((n,c)=>n+combatPower(c)*1.35,0);
 const stability=owned.reduce((n,c)=>n+Number(c.stability||0)+Number(c.approval||0),0)/owned.length*.35;
 return territory+pop+economy+military+stability;
}
function checkVictory(room){
 if(!room.snapshot?.countries)return;const cs=Object.values(room.snapshot.countries),controllers=[...new Set(cs.map(c=>c.controller))];
 if(controllers.length===1){const winner=controllers[0];if(String(winner).startsWith('P:')&&!room.snapshot.winner){room.snapshot.winner=winner;room.snapshot.victoryType='domination';pushLog(room,`انتهت الحرب: ${winner} يسيطر على العالم.`)}return}
 if(Number(room.snapshot.turn||1)<hegemonyStartTurn(room.pace)||room.snapshot.winner)return;
 const human=controllers.filter(x=>String(x).startsWith('P:'));if(!human.length)return;
 const ranked=human.map(controller=>({controller,territories:cs.filter(c=>c.controller===controller).length,score:controllerScore(room,controller)})).sort((a,b)=>b.score-a.score);
 const top=ranked[0],second=ranked[1]?.score||1;
 if(top.territories>=Math.ceil(cs.length*.55)&&top.score>=second*1.25){room.snapshot.winner=top.controller;room.snapshot.victoryType='hegemony';pushLog(room,`نصر هيمنة: ${top.controller} تجاوز 55% من العالم بفارق قوة حاسم.`)}
}
function mutate(room,logText){if(logText)pushLog(room,logText);updateEliminatedPlayers(room);checkVictory(room);room.revision++;markDirty(room);broadcastSync(room);broadcast(room,lobbyPayload(room))}
function actionResult(ws,action,ok,extra={}){send(ws,{type:'actionResult',action,ok,...extra})}
function playerCountry(room,ws){const p=room.players.get(ws.playerId);if(!p?.country)return null;const controller=`P:${p.country}`,original=getCountry(room,p.country);if(original?.controller===controller)return original;return Object.values(room.snapshot?.countries||{}).find(c=>c.controller===controller)||original||null}
function ownedByPlayer(room,ws,country){const p=room.players.get(ws.playerId);return p?.country&&country?.controller===`P:${p.country}`}
function attackCost(from,plan='balanced',naval=false){
 const a=from.army||{},mult=attackPlanCostMultiplier(plan)*(naval?1.18:1);
 const base={food:4+Number(a.soldiers||0)*.08+Number(a.artillery||0)*.12,water:3,fuel:5+Number(a.tanks||0)*.8+Number(a.aircraft||0)*1.2+Number(a.helicopters||0)*.7+(naval?7:0),power:1+Number(a.drones||0)*.08,steel:1+(naval?2:0),money:5+(naval?5:0)};
 return Object.fromEntries(Object.entries(base).map(([k,v])=>[k,v*mult]));
}
function attackPlan(value){const p=attackPlanSpec(value);return {name:p.name,atk:p.attack,exhaustion:p.exhaustion,cp:p.command}}
function ensureGameplayFields(c){c.stock=c.stock||{};c.production=c.production||{};if(c.stock.gold==null)c.stock.gold=30;if(c.production.gold==null)c.production.gold=2;if(c.trainingCamps==null)c.trainingCamps=0;if(c.borderDefense==null)c.borderDefense=0;if(c.recruitedThisTurn==null)c.recruitedThisTurn=0;
 c.warExhaustion=clamp(Number(c.warExhaustion||0),0,100);c.commandPoints=Number.isFinite(Number(c.commandPoints))?Number(c.commandPoints):commandCap(c);c.occupationPolicy=c.occupationPolicy||'balanced';
 for(const k of ['techAgriculture','techIndustry','techLogistics','techArmor','techAir','techIntel'])c[k]=techLevel(c,k);
 for(const k of ['missileStock','missileDefense','missileProgram','electronicWarfare','satelliteRecon'])c[k]=Math.max(0,Math.min(k==='missileStock'?999:5,Number(c[k]||0)));
 if(c.cruiseMissiles==null&&c.ballisticMissiles==null&&c.hypersonicMissiles==null)c.cruiseMissiles=Math.max(0,Number(c.missileStock||0));
 c.cruiseMissiles=Math.max(0,Math.min(999,Number(c.cruiseMissiles||0)));c.ballisticMissiles=Math.max(0,Math.min(999,Number(c.ballisticMissiles||0)));c.hypersonicMissiles=Math.max(0,Math.min(999,Number(c.hypersonicMissiles||0)));c.missileStock=c.cruiseMissiles+c.ballisticMissiles+c.hypersonicMissiles;
 for(const k of ['radarLevel','earlyWarning','carrierStock','submarineStock'])c[k]=Math.max(0,Math.min((k==='carrierStock'||k==='submarineStock')?99:5,Number(c[k]||0)));
 c.airReadiness=clamp(Number(c.airReadiness??70),0,100);c.fleetReadiness=clamp(Number(c.fleetReadiness??70),0,100);
}
function ensureCombatState(room){
 room.snapshot.battles=Array.isArray(room.snapshot.battles)?room.snapshot.battles:[];
 room.snapshot.battles=room.snapshot.battles.slice(-40);
}
function activeBattles(room){ensureCombatState(room);return room.snapshot.battles.filter(b=>b.status==='active')}
function activeBattleFor(room,source,target,attacker){return activeBattles(room).find(b=>b.source===source&&b.target===target&&b.attacker===attacker)||null}
function battleById(room,id){ensureCombatState(room);return room.snapshot.battles.find(b=>b.id===id)||null}
function activeBattleUsingArmy(room,armyId){return activeBattles(room).find(b=>(b.attackerArmyIds||[]).includes(armyId)||(b.defenderArmyIds||[]).includes(armyId))||null}
function fieldArmy(room,id){return (Array.isArray(room.snapshot?.fieldArmies)?room.snapshot.fieldArmies:[]).find(a=>a.id===id)||null}
function fieldArmiesAt(room,owner,location){return (Array.isArray(room.snapshot?.fieldArmies)?room.snapshot.fieldArmies:[]).filter(a=>a.owner===owner&&a.location===location)}
function safeArmyIds(value){if(!Array.isArray(value))return [];return [...new Set(value.map(x=>String(x||'').replace(/[^A-Za-z0-9_-]/g,'').slice(0,64)).filter(Boolean))].slice(0,10)}
function fieldArmyCombatPower(base,a){return combatPower(base,a)*clamp(Number(a.supply||70)/100,.35,1.08)*clamp(Number(a.morale||70)/100,.35,1.08)}
function participantPower(room,base,ids){return (ids||[]).reduce((sum,id)=>{const a=fieldArmy(room,id);return sum+(a?fieldArmyCombatPower(base,a):0)},0)}
function airAssets(country,armies=[]){const raw=Number(country?.army?.aircraft||0)*2+Number(country?.army?.drones||0)+Number(country?.army?.helicopters||0)*.6+armies.reduce((n,a)=>n+Number(a.aircraft||0)*2+Number(a.drones||0)+Number(a.helicopters||0)*.6,0);return raw*(.62+clamp(Number(country?.airReadiness??70),0,100)/260)}
function navalAssets(country){return Number(country?.army?.navy||0)*(.62+clamp(Number(country?.fleetReadiness??70),0,100)/260)}
function battleEncircled(room,battle){const defender=battle.defender,target=battle.target;const friendlyLand=(adjacency[target]||[]).some(n=>getCountry(room,n)?.controller===defender);const friendlySea=(seaLanes[target]||[]).some(n=>getCountry(room,n)?.controller===defender&&seaSupplyAvailable(room,defender,target,n));return !friendlyLand&&!friendlySea}
function retreatOptions(room,owner,from){const land=(adjacency[from]||[]).filter(n=>getCountry(room,n)?.controller===owner),sea=(seaLanes[from]||[]).filter(n=>getCountry(room,n)?.controller===owner&&seaSupplyAvailable(room,owner,from,n));return [...new Set([...land,...sea])]}
