function seaSupplyAvailable(room,controller,a,b){const base=controllerBase(room,controller),ca=getCountry(room,a),cb=getCountry(room,b);return !!(base&&ca?.controller===controller&&cb?.controller===controller&&Number(base.army?.navy||0)>0&&siteFactor(room,a,'port')>.25&&siteFactor(room,b,'port')>.25)}
