function safeSiteId(v){return String(v||'').replace(/[^A-Za-z0-9_-]/g,'').slice(0,64)}
function sites(room,countryId,kind=null){const xs=Array.isArray(room.snapshot?.strategicSites)?room.snapshot.strategicSites:[];return xs.filter(s=>s.countryId===countryId&&(!kind||s.kind===kind))}
